/**
 * The seccomp filter bwrap installs while an escape socket directory exists, such as WSL's interop directory: a
 * classic BPF program that refuses `socket(AF_VSOCK, …)`, the transport WSL's interop and its Windows-side services
 * run over, and `io_uring_setup`, because an io_uring `IORING_OP_SOCKET` request creates a socket without the
 * `socket` system call the filter sees. Every other system call is allowed, so commands behave as without the filter.
 *
 * The program is written out here instruction by instruction rather than generated by libseccomp, so the whole policy
 * can be read in this file. It handles each architecture a WSL kernel or a Linux host runs commands under: x86-64
 * (with the x32 numbering), i386 (a 32-bit process on an x86-64 kernel), AArch64 and 32-bit Arm. A 32-bit process may
 * create a socket through the multiplexing `socketcall` call, whose arguments lie in memory the filter cannot read;
 * the filter refuses its `SYS_SOCKET` form for every family, so a 32-bit program that creates sockets that way gets
 * `EAFNOSUPPORT`. bwrap reads the program from a file descriptor, so {@link withSeccompFilter} starts bwrap from
 * `/bin/sh`, which writes the program into a pipe on descriptor 3 with its `printf` builtin; nothing is written to disk.
 *
 * @module @deepseek-ai/dsh-sandbox-local/seccomp
 */

import { assertNever } from '@deepseek-ai/dsh-util-values'

/** `struct seccomp_data` offsets: the system call number, the architecture, and the low half of the first argument. */
const DATA_NR = 0
const DATA_ARCH = 4
/** `args[0]` starts at offset 16; every architecture here is little-endian, so its low 32 bits come first. */
const DATA_ARG0_LOW = 16

/** Classic BPF opcodes: load a word at an absolute offset, jump if equal to a constant, return a constant. */
const BPF_LD_W_ABS = 0x20
const BPF_JEQ_K = 0x15
const BPF_RET_K = 0x06

/** Seccomp actions. */
const SECCOMP_RET_ALLOW = 0x7fff_0000
const SECCOMP_RET_ERRNO = 0x0005_0000

/** Errors the refused calls return; the same numbers on every architecture here. */
const ENOSYS = 38
const EAFNOSUPPORT = 97

/** `AF_VSOCK`, the virtual-machine socket family. */
const AF_VSOCK = 40
/** `socketcall`'s first argument for `socket`. */
const SYS_SOCKET = 1
/** The x32 system call numbers' marker bit on x86-64. */
const X32_SYSCALL_BIT = 0x4000_0000

/** The architectures, as `AUDIT_ARCH_*`, and their numbers for the calls the filter inspects. */
const ARCHITECTURES = [
  { name: 'x86-64', audit: 0xc000_003e, socket: [41, X32_SYSCALL_BIT | 41], socketcall: [], ioUringSetup: [425, X32_SYSCALL_BIT | 425] },
  { name: 'i386', audit: 0x4000_0003, socket: [359], socketcall: [102], ioUringSetup: [425] },
  { name: 'aarch64', audit: 0xc000_00b7, socket: [198], socketcall: [], ioUringSetup: [425] },
  { name: 'arm', audit: 0x4000_0028, socket: [281], socketcall: [102], ioUringSetup: [425] },
] as const

/** One instruction, with jump targets named by label until {@link assemble} resolves them. */
export type Instruction =
  | { readonly op: 'load'; readonly offset: number }
  | { readonly op: 'jeq'; readonly value: number; readonly then: string; readonly otherwise?: string }
  | { readonly op: 'return'; readonly action: number }
  | { readonly op: 'label'; readonly name: string }

/**
 * The filter's instructions. Each architecture's block loads the call number and jumps to the check for a call it
 * inspects; anything else falls through to allow.
 * @returns the instructions with labels.
 */
function program(): Instruction[] {
  const steps: Instruction[] = [{ op: 'load', offset: DATA_ARCH }]
  for (const arch of ARCHITECTURES) steps.push({ op: 'jeq', value: arch.audit, then: arch.name })
  steps.push({ op: 'return', action: SECCOMP_RET_ALLOW })
  for (const arch of ARCHITECTURES) {
    steps.push({ op: 'label', name: arch.name }, { op: 'load', offset: DATA_NR })
    for (const nr of arch.socket) steps.push({ op: 'jeq', value: nr, then: 'family' })
    for (const nr of arch.socketcall) steps.push({ op: 'jeq', value: nr, then: 'socketcall' })
    for (const nr of arch.ioUringSetup) steps.push({ op: 'jeq', value: nr, then: 'nosys' })
    steps.push({ op: 'return', action: SECCOMP_RET_ALLOW })
  }
  steps.push(
    // socket(family, …): only the family's low 32 bits reach the kernel, which reads it as an int.
    { op: 'label', name: 'family' },
    { op: 'load', offset: DATA_ARG0_LOW },
    { op: 'jeq', value: AF_VSOCK, then: 'afnosupport', otherwise: 'allow' },
    // socketcall(call, args): the family lies in memory, so every SYS_SOCKET call is refused.
    { op: 'label', name: 'socketcall' },
    { op: 'load', offset: DATA_ARG0_LOW },
    { op: 'jeq', value: SYS_SOCKET, then: 'afnosupport', otherwise: 'allow' },
    { op: 'label', name: 'afnosupport' },
    { op: 'return', action: SECCOMP_RET_ERRNO | EAFNOSUPPORT },
    { op: 'label', name: 'nosys' },
    { op: 'return', action: SECCOMP_RET_ERRNO | ENOSYS },
    { op: 'label', name: 'allow' },
    { op: 'return', action: SECCOMP_RET_ALLOW },
  )
  return steps
}

/**
 * Encode instructions as `struct sock_filter` entries: a 16-bit code, two 8-bit jump offsets counted from the next
 * instruction, and a 32-bit constant, little-endian. A missing `otherwise` falls through.
 * @param steps - the instructions with labels.
 * @returns the program's bytes.
 * @throws {Error} when a label is missing or a jump goes backwards or further than 255 instructions.
 */
export function assemble(steps: readonly Instruction[]): Buffer {
  const code = steps.filter((step): step is Exclude<Instruction, { op: 'label' }> => step.op !== 'label')
  const labels = new Map<string, number>()
  let index = 0
  for (const step of steps) {
    if (step.op === 'label') labels.set(step.name, index)
    else index += 1
  }
  const bytes = Buffer.alloc(code.length * 8)
  code.forEach((step, at) => {
    const offset = (label: string | undefined): number => {
      if (label === undefined) return 0
      const target = labels.get(label)
      if (target === undefined) throw new Error(`seccomp filter: no label ${label}`)
      const distance = target - at - 1
      if (distance < 0 || distance > 255) throw new Error(`seccomp filter: the jump to ${label} cannot be encoded`)
      return distance
    }
    switch (step.op) {
      case 'load': bytes.writeUInt16LE(BPF_LD_W_ABS, at * 8); bytes.writeUInt32LE(step.offset, at * 8 + 4); break
      case 'jeq':
        bytes.writeUInt16LE(BPF_JEQ_K, at * 8)
        bytes.writeUInt8(offset(step.then), at * 8 + 2)
        bytes.writeUInt8(offset(step.otherwise), at * 8 + 3)
        bytes.writeUInt32LE(step.value >>> 0, at * 8 + 4)
        break
      case 'return': bytes.writeUInt16LE(BPF_RET_K, at * 8); bytes.writeUInt32LE(step.action >>> 0, at * 8 + 4); break
      /* v8 ignore next -- labels were filtered out of this closed union above */
      default: assertNever(step)
    }
  })
  return bytes
}

/** The assembled filter. */
export const ESCAPE_FILTER: Buffer = assemble(program())

/**
 * The filter as a `printf` format: every byte as a three-digit octal escape, so no `%`, backslash or NUL reaches the
 * shell unescaped.
 */
const ESCAPE_FILTER_FORMAT = [...ESCAPE_FILTER].map(byte => `\\${byte.toString(8).padStart(3, '0')}`).join('')

/**
 * The loader script. It keeps the caller's standard input on descriptor 4, writes the program into a pipe, and runs
 * bwrap with the pipe on descriptor 3 and the original standard input back on 0; bwrap's exit status is the script's.
 */
const LOADER = 'f=$1; shift; exec 4<&0; printf "$f" 4<&- | exec "$@" 3<&0 0<&4 4<&-'

/**
 * Start a bwrap invocation through the loader so that bwrap installs {@link ESCAPE_FILTER}.
 * @param bwrap - bwrap and its profile arguments, without the trailing `--` and command.
 * @returns the invocation, with `--seccomp 3` added, to which the caller appends `--` and the command.
 */
export function withSeccompFilter(bwrap: readonly string[]): string[] {
  return ['/bin/sh', '-c', LOADER, 'sh', ESCAPE_FILTER_FORMAT, ...bwrap, '--seccomp', '3']
}
